import { _decorator, Component, instantiate, Label, Node, Sprite, SpriteFrame, tween, Tween, UIOpacity, Vec3 } from 'cc';

const { ccclass, property } = _decorator;

// 節點命名 prefab 需照這組名稱擺放
const NODE_SLOTS = 'slots';
const NODE_TEMPLATE = 'win_feed_item';
const NODE_COUNT = 'count';
const NODE_SYMBOL = 'symbol';
const NODE_AMOUNT = 'amount';
const NODE_GLOW = 'effects';
const SLOT_COUNT = 5;
const ENTER_SCALE = 0.6;

/**
 * 連線消除贏分小看板：最多 SLOT_COUNT 則，最新的出現在 slot_0，其他則依序下移，滿了收掉最舊一則。
 * 以 win_feed_item 為樣板複製出所有則，位置由 slots/slot_N 決定。
 */
@ccclass('1002/WinFeed')
export class WinFeed extends Component {
    // 樣板節點 沒指定時找名為 win_feed_item 的子節點
    @property(Node)
    itemTemplate: Node | null = null;

    private slots: Node[] = [];
    // 全部可用的則
    private pool: Node[] = [];
    // 目前顯示中的則 由新到舊
    private shown: Node[] = [];

    protected override onLoad(): void {
        const slotsRoot = this.node.getChildByName(NODE_SLOTS);
        const template = this.itemTemplate ?? this.node.getChildByName(NODE_TEMPLATE);
        if (!slotsRoot || !template) {
            console.warn(`[WinFeed] ${this.node.name} 缺少 ${NODE_SLOTS} 或 ${NODE_TEMPLATE}`);
            return;
        }
        for (let i = 0; i < SLOT_COUNT; i++) {
            const slot = slotsRoot.getChildByName(`slot_${i}`);
            if (!slot) {
                console.warn(`[WinFeed] ${this.node.name} 缺少 ${NODE_SLOTS}/slot_${i}`);
                return;
            }
            this.slots.push(slot);
        }
        template.active = false;
        this.pool.push(template);
        for (let i = 1; i < SLOT_COUNT; i++) {
            const item = instantiate(template);
            item.active = false;
            template.parent!.addChild(item);
            this.pool.push(item);
        }
    }

    /**
     * 新增一則，最新的出現在最上面，其他則下移一格。
     *
     * @param count 中獎個數
     * @param frame 符號圖
     * @param amount 已格式化的贏分
     * @param duration 出現與下移的秒數
     */
    push(count: number, frame: SpriteFrame | null, amount: string, duration: number): void {
        if (this.pool.length === 0) return;
        // 上一則動畫還沒播完就直接到定位
        this.settle();
        if (this.shown.length >= this.slots.length) {
            this.shown.pop()!.active = false;
        }
        const item = this.pool.find((node) => this.shown.indexOf(node) < 0)!;
        this.shown.forEach((node, index) => {
            tween(node)
                .to(duration, { position: this.slotPosition(index + 1) }, { easing: 'quadOut' })
                .start();
        });
        this.fill(item, count, frame, amount);
        this.shown.unshift(item);
        this.playEnter(item, duration);
    }

    /** 所有顯示中的則立刻到各自定位 */
    private settle(): void {
        this.shown.forEach((node, index) => {
            Tween.stopAllByTarget(node);
            const opacity = this.opacityOf(node);
            Tween.stopAllByTarget(opacity);
            node.setPosition(this.slotPosition(index));
            node.setScale(1, 1, 1);
            opacity.opacity = 255;
            const glow = node.getChildByName(NODE_GLOW);
            if (glow) {
                Tween.stopAllByTarget(this.opacityOf(glow));
                glow.active = false;
            }
        });
    }

    /** 填入個數 符號 贏分 */
    private fill(item: Node, count: number, frame: SpriteFrame | null, amount: string): void {
        const countLabel = item.getChildByName(NODE_COUNT)?.getComponent(Label);
        const symbolSprite = item.getChildByName(NODE_SYMBOL)?.getComponent(Sprite);
        const amountLabel = item.getChildByName(NODE_AMOUNT)?.getComponent(Label);
        if (!countLabel || !symbolSprite || !amountLabel) {
            console.warn(`[WinFeed] ${NODE_TEMPLATE} 缺少 ${NODE_COUNT} ${NODE_SYMBOL} 或 ${NODE_AMOUNT}`);
            return;
        }
        countLabel.string = `${count}`;
        symbolSprite.spriteFrame = frame;
        amountLabel.string = amount;
    }

    /** 新的一則在第一格放大出現並發光 */
    private playEnter(item: Node, duration: number): void {
        item.active = true;
        item.setPosition(this.slotPosition(0));
        item.setScale(ENTER_SCALE, ENTER_SCALE, 1);
        tween(item).to(duration, { scale: new Vec3(1, 1, 1) }, { easing: 'backOut' }).start();
        const opacity = this.opacityOf(item);
        opacity.opacity = 0;
        tween(opacity).to(duration, { opacity: 255 }).start();
        const glow = item.getChildByName(NODE_GLOW);
        if (glow) {
            const glowOpacity = this.opacityOf(glow);
            glow.active = true;
            glowOpacity.opacity = 255;
            tween(glowOpacity)
                .to(duration * 2, { opacity: 0 })
                .call(() => (glow.active = false))
                .start();
        }
    }

    /** 第 index 格在本節點座標系的位置 */
    private slotPosition(index: number): Vec3 {
        const out = new Vec3();
        this.node.inverseTransformPoint(out, this.slots[index].worldPosition);
        return out;
    }

    private opacityOf(node: Node): UIOpacity {
        return node.getComponent(UIOpacity) ?? node.addComponent(UIOpacity);
    }
}
