import type { SlotColumn, SlotGrid, SlotGridLayout } from '../models/SlotGrid';
import type { SlotAwardPosition } from '../models/SlotRound';
import type { SlotApiBoard } from './SlotApiTypes';
import { BOOM_SYMBOL_ID, multiplierSymbolIdOf } from '../config/SlotGameDefinition';

/**
 * 純資料 decoder：把後端的盤面（`rl`）拆成前端用的盤面，
 * 以及把格子位置換回盤面座標。本款每一格都計分，沒有隱藏列。
 */
export class SlotGridDecoder {
    /**
     * @param layout 盤面的形狀。
     */
    constructor(private readonly layout: SlotGridLayout) {}

    /**
     * 把一張盤面解成前端用的盤面，過程中先驗證維度是否相符。
     *
     * 維度對不起來時丟例外而不是默默修正：那代表本地登記的盤面形狀跟後端不同步，硬解下去會整盤錯位。
     * 球的符號 id 一律是 {@link BOOM_SYMBOL_ID}，面值在格子標記 `co`，這裡換成一個面值一個 id 的倍率球。
     *
     * @param board 後端的盤面。
     * @returns 前端用的盤面。
     * @throws 欄數或任一欄的格數跟設定不符、或球沒有已登記的面值時丟 RangeError。
     */
    decode(board: Pick<SlotApiBoard, 'rl' | 'co'>): SlotGrid {
        const { rl, co } = board;
        if (rl.length !== this.layout.columns) {
            throw new RangeError(`Board column count mismatch: rl=${rl.length}, layout=${this.layout.columns}`);
        }
        const rows = this.layout.visibleRows;
        const columns: SlotColumn[] = rl.map((full, index) => {
            if (full.length !== rows) {
                throw new RangeError(`Board column ${index} has ${full.length} rows; expected ${rows}`);
            }
            return { index, symbolIds: full.map((symbolId, row) => (symbolId === BOOM_SYMBOL_ID ? this.ballSymbolId(co, index * rows + row) : symbolId)) };
        });
        return { layout: { ...this.layout }, columns };
    }

    /**
     * 把格子位置換成盤面座標。
     *
     * 位置是逐軸加總的編號：位置 = 軸 × 列數 + 列。
     *
     * @param position 格子位置。
     * @returns 盤面座標；超出範圍時 null。
     */
    toCell(position: number): SlotAwardPosition | null {
        const rows = this.layout.visibleRows;
        const col = Math.floor(position / rows);
        return position >= 0 && col < this.layout.columns ? { col, row: position % rows } : null;
    }

    private ballSymbolId(co: SlotApiBoard['co'], position: number): number {
        const value = co?.[String(position)]?.x;
        const symbolId = value === undefined ? undefined : multiplierSymbolIdOf(value);
        if (symbolId === undefined) throw new RangeError(`Ball at ${position} has unknown value ${value}`);
        return symbolId;
    }
}
