import { _decorator, Button, Component, Label, Node, Prefab, sp, Sprite, sys, UITransform, Vec3, view } from "cc";
import { AdapterNode } from "./AdapterNode";
import { SlotMachineView } from "../reel/view/SlotMachineView";
import type { SlotMachineModel } from "../reel/model/SlotMachineModel";
import { BaseToggle } from "./BaseToggle";
import { WinFeed } from "./WinFeed";

const { ccclass, property } = _decorator;

/**
 * 把介面根節點撐成安全區大小 子節點的 Widget 才會貼著安全區的邊
 * 橫版只套用左右 上下不內縮
 *
 * @param node 介面根節點 父節點的縮放會被扣掉 讓縮放後剛好等於安全區
 */
export function fitViewToSafeArea(node: Node): void {
    const transform = node.getComponent(UITransform);
    const scale = node.parent?.worldScale;
    if (!transform || !scale || scale.x === 0 || scale.y === 0) return;
    const rawSafe = sys.getSafeAreaRect();
    const visible = view.getVisibleSize();
    // 安全區與可視範圍取交集 超出的不算
    const safeLeft = Math.max(rawSafe.x, 0);
    const safeBottom = Math.max(rawSafe.y, 0);
    const safe = {
        x: safeLeft,
        y: safeBottom,
        width: Math.min(rawSafe.x + rawSafe.width, visible.width) - safeLeft,
        height: Math.min(rawSafe.y + rawSafe.height, visible.height) - safeBottom,
    };
    // 橫版只避開左右 上下維持貼邊
    const landscape = visible.width > visible.height;
    const safeY = landscape ? 0 : safe.y;
    const safeHeight = landscape ? visible.height : safe.height;
    const width = safe.width / scale.x;
    const height = safeHeight / scale.y;
    transform.setContentSize(width, height);
    // 安全區中心偏移時用錨點補償 沒加 Widget 的子節點位置不動
    const offsetX = (safe.x + safe.width / 2 - visible.width / 2) / scale.x;
    const offsetY = (safeY + safeHeight / 2 - visible.height / 2) / scale.y;
    transform.setAnchorPoint(0.5 - offsetX / width, 0.5 - offsetY / height);
}

@ccclass("1002/GameViewAdapter")
export class GameViewAdapter extends Component {

    // runtime model（各 view 各自持有）
    slotMachineModel: SlotMachineModel = null!;

    // 彈窗根節點（BuyFeature / Jackpot 都會 reparent 到此）
    @property(Node)
    popupRoot: Node = null!;

    // 各彈窗的 prefab 路徑（留空則 fallback 到 GameContext 的預設路徑）
    @property(Prefab)
    winAnimationPrefab: Prefab | null = null;

    @property({ tooltip: "buyFeaturePopup prefab 路徑（留空用預設）" })
    buyFeaturePrefabPath: string = '';

    @property(Prefab)
    freeBoardPrefab: Prefab | null = null;

    // === 彈窗節點 transform 覆寫（給直版微調用，留 (0,0,0) 表示不覆寫）===
    @property({ tooltip: "WinAnimationView 內容子節點位置覆寫（(0,0,0) = 不覆寫）" })
    winAnimationContentLpos: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: "WinAnimationView 內容子節點縮放覆寫（(0,0,0) = 不覆寫）" })
    winAnimationContentScale: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: "BuyFeaturePopupView 內容子節點位置覆寫（(0,0,0) = 不覆寫）" })
    buyFeatureContentLpos: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: "BuyFeaturePopupView 內容子節點縮放覆寫（(0,0,0) = 不覆寫）" })
    buyFeatureContentScale: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: "FreeBoardView 內容子節點位置覆寫（(0,0,0) = 不覆寫）" })
    freeBoardContentLpos: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: "FreeBoardView 內容子節點縮放覆寫（(0,0,0) = 不覆寫）" })
    freeBoardContentScale: Vec3 = new Vec3(0, 0, 0);

    // 背景
    @property(Node)
    bg: Node = null!;

    // 動態背景 spine（NG/FG）
    @property(sp.Skeleton)
    backgroundMain: sp.Skeleton = null!;

    @property(sp.Skeleton)
    backgroundFree: sp.Skeleton = null!;

    // mosaic 過場 Sprite
    @property(Sprite)
    bgFreeSprite: Sprite = null!;

    // 特效 spine
    @property(sp.Skeleton)
    collectSkel: sp.Skeleton = null!;

    @property(sp.Skeleton)
    transitionSkel: sp.Skeleton | null = null;

    // 角色 spine
    @property(sp.Skeleton)
    cha001Skel: sp.Skeleton = null!;

    // 轉輪
    @property(SlotMachineView)
    slotMachineView: SlotMachineView = null!;

    // 購買按鈕
    @property(Button)
    buySuperBtn: Button = null!;

    @property({ type: Node, tooltip: '輪帶框 震動時只搖這個節點與輪帶' })
    reelBg: Node | null = null;

    // 輪帶底圖 NG/FG
    @property(Node)
    reelBgNg: Node | null = null;

    @property(Node)
    reelBgFg: Node | null = null;

    // 加注區塊與開關
    @property(Node)
    extraBetBg: Node = null!;

    @property(BaseToggle)
    extraBetToggle: BaseToggle = null!;

    // 連線消除贏分小看板
    @property(WinFeed)
    winFeed: WinFeed | null = null;

    // JP 標籤
    @property({ type: Label, tooltip: 'FG 累積倍率計數器 (frame_total_multiplier → Label 組件)' })
    frameTotalMultiplierLabel: Label = null!;

    @property({ type: sp.Skeleton, tooltip: 'FG 累積倍率計數器變動動效 (frame_total_multiplier → ui_mul spine)' })
    frameTotalMultiplierSpine: sp.Skeleton | null = null;

    // === win_bar（中獎累計條）===
    @property(Node)
    winBarNode: Node = null!;

    @property(sp.Skeleton)
    winBarSkel: sp.Skeleton = null!;

    @property(Label)
    winBarNumLabel: Label = null!;

    @property(Node)
    winBarMulNode: Node = null!;

    @property(Label)
    winBarMulLabel: Label = null!;

    /**
     * 依加注狀態更新顯示。
     *
     * @param state available 為 false 時隱藏整個加注區塊；enabled 為開關狀態，開啟時購買鈕不可互動。
     */
    applyExtraBet(state: { available: boolean; enabled: boolean }): void {
        if (this.extraBetBg?.isValid) this.extraBetBg.active = state.available;
        this.extraBetToggle?.setToggle(state.enabled);
        // 加注開著購買鈕不可互動
        if (this.buySuperBtn?.isValid) this.buySuperBtn.interactable = !state.enabled;
    }

    protected override onLoad(): void {
        super.onLoad?.();
        // 動態背景 spine 跟 bg 一樣依可視範圍等比鋪滿
        for (const background of [this.backgroundMain, this.backgroundFree]) {
            if (background && !background.node.getComponent(AdapterNode)) background.node.addComponent(AdapterNode);
        }
        this.fitToSafeArea();
        view.on('design-resolution-changed', this.fitToSafeArea, this);
    }

    protected override onDestroy(): void {
        view.off('design-resolution-changed', this.fitToSafeArea, this);
        super.onDestroy?.();
    }

    // 撐成安全區大小
    private fitToSafeArea(): void {
        fitViewToSafeArea(this.node);
    }
}
