import type { WinTierThreshold } from './GameConst';

/**
 * 贏分展示相關的執行期資料。不寫進共用的 SlotGameStore。
 */
export default class PresentationStore {
    private static instance: PresentationStore;
    /**
     * @returns 全域唯一的 PresentationStore；第一次呼叫時建立。
     */
    static getInstance(): PresentationStore {
        if (!PresentationStore.instance) {
            PresentationStore.instance = new PresentationStore();
        }
        return PresentationStore.instance;
    }

    private _winTiers: readonly WinTierThreshold[] = [];
    /**
     * 目前的大獎演出門檻，進場前是空的。
     *
     * @returns 由大到小的門檻。
     */
    get winTiers(): readonly WinTierThreshold[] {
        return this._winTiers;
    }
    /**
     * 進場時寫入後端給的大獎演出門檻。
     *
     * @param tiers 由大到小的門檻。
     */
    setWinTiers(tiers: readonly WinTierThreshold[]): void {
        this._winTiers = tiers;
    }
}
