// 贏分演出等級
export const WinTier = {
    WIN: 'win',
    BIG: 'big',
    MEGA: 'mega',
    SUPER: 'super',
    EPIC: 'epic',
    TOTAL: 'total',
} as const;
export type WinTier = (typeof WinTier)[keyof typeof WinTier];

// 贏分演出門檻 倍率達到 min 就是這一檔 由大到小排
export interface WinTierThreshold {
    readonly min: number;
    readonly key: WinTier;
}
