import { ReelModel } from "./ReelModel";
import { TypedEventBus } from "../../events/TypedEventBus";

export enum SlotMachineState {
    IDLE,
    SPINNING,
    STOPPING
}

/** SlotMachineModel 是每個 view 各自持有的實例，state 變化只跟該實例有關，
 *  故用自己的 TypedEventBus，不共用全域 gameRuntimeEventBus */
export interface SlotMachineModelEvents {
    stateChanged: { previousState: SlotMachineState; state: SlotMachineState };
}

export class SlotMachineModel {
    /** registry 用的 model 識別字串，對應原本 mobx-keystone @model('store/SlotMachineModel') */
    public readonly $modelType = 'store/SlotMachineModel';

    readonly events = new TypedEventBus<SlotMachineModelEvents>();

    private _state: SlotMachineState = SlotMachineState.IDLE;
    get state(): SlotMachineState { return this._state; }

    private _stopCount: number = 0;
    get stopCount(): number { return this._stopCount; }
    setStopCount(stopCount: number): void { this._stopCount = stopCount; }

    /** 由 caller 傳入（prefab 的 reelViews.length），沒傳預設 0 */
    private _reelCount: number = 0;
    get reelCount(): number { return this._reelCount; }
    setReelCount(reelCount: number): void { this._reelCount = reelCount; }

    reelModels: ReelModel[] = [];
    spinStartTime: number = 0;
    stripLength: number = 0;//固定滾輪條長度
    stopcount: number = 0;//目前滾輪停止數

    /** 保留建構子參數是為了相容 GameMain_1001/1002 裡
     *  `new SlotMachineModel({ reelCount: v.slotMachineView.reelViews.length })` 的舊呼叫方式 */
    constructor(props?: { reelCount?: number }) {
        this._reelCount = props?.reelCount ?? 0;
    }

    setState(state: SlotMachineState): void {
        const previousState = this._state;
        if (previousState === state) return;
        this._state = state;
        this.events.emit("stateChanged", { previousState, state });
    }

    /** 原本由 onAttachedToRootStore() 觸發，改由 caller 在 new SlotMachineModel() 後手動呼叫，
     *  這樣 AppStore 的 registry 才能移除 mobx-keystone 的 registerRootStore 依賴 */
    initReelModels(): void {
        for (let i = 0; i < this.reelCount; i++) {
            const reelModel = new ReelModel({});
            reelModel.reelIndex = i;
            this.reelModels.push(reelModel);
        }
    }

    spin(): void {
        this.spinStartTime = Date.now();
        this.setState(SlotMachineState.SPINNING);
    }

    onAllStopped(): void {
        this.setState(SlotMachineState.IDLE);
    }

    getReelModel(index: number): ReelModel {
        return this.reelModels[index];
    }
}
