import { _decorator, Button, Node, Sprite, SpriteFrame } from 'cc';
import { EventComponent } from '../../events/EventComponent';
import { ButtonState } from './ButtonState';
import { ButtonVariant } from './ButtonVariant';

const { ccclass, property } = _decorator;

/**
 * 按鈕的「型態 × 狀態」兩軸外觀管理：型態決定用哪一組圖，狀態決定用那組裡的哪一張。
 *
 * 移植自 entry 的 `lobby/scripts/base/BaseButton`，保留它「型態 × 狀態」兩軸的 API
 * （`setVariant()`／`setInteractable()`／`setState()`／可覆寫的 `onStateChanged()`），
 * 但換了實作機制，因為兩邊的美術結構不同：
 *
 * - **狀態表現**：lobby 在 `Property` 子節點下掛四個 Sprite 切 `active`；1002 的按鈕是
 *   單一 Sprite、一個狀態一張 PNG，所以這裡改成直接換 `spriteFrame`，不動節點結構。
 * - **型態軸**：lobby 寫死顏色 enum，1002 每顆按鈕的型態語意都不一樣，改成 prefab 自己
 *   列 {@link ButtonVariant} 陣列。
 * - **按壓回饋**：由 `cc.Button` 的 `transition = COLOR` 負責（2026-10-30 前是 SCALE），這支不碰，所以
 *   {@link ButtonState} 沒有 Pressed。停用時 cc.Button 也會染上停用色，疊在這支換上的停用圖上。
 *
 * **這支不接管點擊。** TemplateView 用 `Button.EventType.CLICK` 綁點擊是刻意的——節點層級的
 * `TOUCH_END` 不看 `interactable`，接手會讓玩家在轉動中還能改注金（見 TemplateView.bindButtons）。
 *
 * 用法：`interactable` 請一律走 {@link setInteractable}，直接寫 `cc.Button.interactable`
 * 這支看不到，圖不會跟著換。
 */
@ccclass('1002/BaseButton')
export class BaseButton extends EventComponent {
    @property({ type: Sprite, displayName: '換圖目標', tooltip: '留空時抓本節點上的 Sprite' })
    target: Sprite = null!;

    @property({ type: [ButtonVariant], displayName: '型態列表' })
    variants: ButtonVariant[] = [];

    @property({ displayName: '預設型態', tooltip: '型態列表的索引' })
    defaultVariant: number = 0;

    @property({ displayName: '預設禁用' })
    defaultDisabled: boolean = false;

    @property({
        displayName: '無禁用圖時轉灰階',
        tooltip: '型態沒給禁用圖時，改用 Sprite 的灰階來表示禁用。minus／plus 這類只有一張圖的按鈕要開。',
    })
    grayscaleWhenNoDisableFrame: boolean = true;

    private _button: Button = null!;
    private _state: ButtonState = ButtonState.Normal;
    private _variantIndex: number = 0;

    /** 是否已經套過 prefab 上的預設禁用值。只在第一次啟用時套一次。 */
    private _defaultApplied: boolean = false;

    /** onEnable 綁上、onDisable 解掉的監聽。不走 trackDisposer——那是 onDestroy 才清，會重複綁。 */
    private _listenerDisposers: Array<() => void> = [];

    /** 目前的外觀狀態 */
    public get state(): ButtonState {
        return this._state;
    }

    /** 目前的型態索引 */
    public get variantIndex(): number {
        return this._variantIndex;
    }

    /** 目前型態的圖組；索引越界時回 null */
    public get variant(): ButtonVariant | null {
        return this.variants[this._variantIndex] ?? null;
    }

    // ******************** 生命週期 ************************

    /**
     * 套用 prefab 上的預設型態。
     */
    protected override onLoad(): void {
        this.ensureInitialized();
        // 型態列表留空是合法用法（只靠灰階表示禁用），不要在這裡 warn
        if (this.variants.length > 0) this.setVariant(this.defaultVariant);
    }

    /**
     * 套用禁用狀態並綁上滑鼠事件。
     *
     * 只有**第一次**啟用才讀 prefab 上的 {@link defaultDisabled}；之後重新啟用改成沿用目前的
     * `interactable`，否則會把別處（`SpinStartStatus` 等）設下的禁用狀態洗掉——節點被關掉再
     * 打開是常態，每次都套回 prefab 預設值等於把執行期的狀態清掉。
     */
    protected override onEnable(): void {
        this.ensureInitialized();

        if (this._defaultApplied) {
            this.setState(this._button?.interactable ? ButtonState.Normal : ButtonState.Disable);
        } else {
            this._defaultApplied = true;
            this.setInteractable(!this.defaultDisabled);
        }

        this.registerEvents();
    }

    /**
     * 解掉滑鼠事件。節點每次關閉都要解，否則下次 onEnable 會重複綁。
     */
    protected override onDisable(): void {
        this.unregisterEvents();
    }

    /**
     * 解掉滑鼠事件後交回基底處理其餘清理。
     */
    public override onDestroy(): void {
        this.unregisterEvents();
        super.onDestroy();
    }

    /**
     * 補抓 `cc.Button` 與換圖目標。可以重複呼叫，抓過就不再找。
     */
    private ensureInitialized(): void {
        if (!this._button) this._button = this.getComponent(Button)!;
        if (!this.target) this.target = this.getComponent(Sprite)!;
    }

    // ******************** 事件 ************************

    /**
     * 綁滑鼠進出。兩個 handler 都先看 `interactable`，禁用中不改外觀。
     */
    private registerEvents(): void {
        const bindings: Array<[string, () => void]> = [
            [Node.EventType.MOUSE_ENTER, this.onMouseEnter],
            [Node.EventType.MOUSE_LEAVE, this.onMouseLeave],
        ];

        for (const [type, handler] of bindings) {
            this.node.on(type, handler, this);
            this._listenerDisposers.push(() => this.node.off(type, handler, this));
        }
    }

    /** 解掉 registerEvents() 綁的所有監聽 */
    private unregisterEvents(): void {
        for (const dispose of this._listenerDisposers) dispose();
        this._listenerDisposers.length = 0;
    }

    /**
     * 滑入時切成懸浮外觀。禁用中不改，否則鎖住的按鈕會因為滑過而亮起來。
     */
    private onMouseEnter(): void {
        if (!this._button?.interactable) return;
        this.setState(ButtonState.Hover);
    }

    /**
     * 滑出時切回一般外觀。禁用中不改，理由同 {@link onMouseEnter}。
     */
    private onMouseLeave(): void {
        if (!this._button?.interactable) return;
        this.setState(ButtonState.Normal);
    }

    // ******************** 對外 API ************************

    /**
     * 切換型態，同時套用目前狀態的圖。
     *
     * @param variant 型態列表的索引，或 {@link ButtonVariant.name}。
     * @returns 有沒有切成功；找不到該型態時回 false 並留在原本的型態。
     */
    public setVariant(variant: number | string): boolean {
        this.ensureInitialized();

        const index =
            typeof variant === 'number' ? variant : this.variants.findIndex((v) => v.name === variant);

        if (index < 0 || index >= this.variants.length) {
            console.warn(`[BaseButton] "${this.node.name}" 找不到型態 ${JSON.stringify(variant)}`);
            return false;
        }

        this._variantIndex = index;
        this.applyFrame();
        return true;
    }

    /**
     * 設定可否點擊，並連帶把外觀換成一般／禁用。
     *
     * 這是 `cc.Button.interactable` 的唯一入口：直接寫 `cc.Button` 這支看不到，圖不會換。
     *
     * @param toggle true 代表可以點。
     */
    public setInteractable(toggle: boolean): void {
        this.ensureInitialized();

        if (!this._button) {
            console.warn(`[BaseButton] "${this.node.name}" 找不到 cc.Button`);
            return;
        }

        this._button.interactable = toggle;
        this.setState(toggle ? ButtonState.Normal : ButtonState.Disable);
    }

    /**
     * 直接指定外觀狀態。一般情況不需要自己呼叫，交給 setInteractable() 與滑鼠事件即可。
     *
     * @param state 要切到的狀態。
     */
    public setState(state: ButtonState): void {
        this.ensureInitialized();

        this._state = state;
        this.applyFrame();
        this.onStateChanged(state);
    }

    // ******************** 換圖 ************************

    /**
     * 依目前的型態與狀態挑一張圖寫進 Sprite。
     *
     * 該狀態沒給圖時退回一般圖——美術只出一張的按鈕不必硬湊三張。禁用狀態退回一般圖時，
     * 若 {@link grayscaleWhenNoDisableFrame} 為真就改用 Sprite 的灰階表示，否則外觀會
     * 完全看不出按鈕被鎖住（1002 的 ic_minus／ic_plus 就是只有一張圖）。
     *
     * 型態列表留空的按鈕（圖由別處管，例如 spin 的箭頭）在這裡直接返回，不碰 `spriteFrame`
     * 也不碰灰階。
     */
    private applyFrame(): void {
        if (!this.target) return;

        const variant = this.variant;
        if (!variant) return;

        let frame: SpriteFrame | null = variant.normal;
        let grayscale = false;

        if (this._state === ButtonState.Hover) {
            frame = variant.hover ?? variant.normal;
        } else if (this._state === ButtonState.Disable) {
            if (variant.disable) frame = variant.disable;
            else grayscale = this.grayscaleWhenNoDisableFrame;
        }

        if (frame) this.target.spriteFrame = frame;
        this.target.grayscale = grayscale;
    }

    // ******************** 可覆寫 ************************

    /**
     * 狀態切換後呼叫，子類可覆寫做額外演出。
     *
     * @param state 切換後的狀態。
     */
    protected onStateChanged(state: ButtonState): void {}
}
